"Compra e vende veículos, casas e mais. Carros, casas e tudo o resto, num toque.": "Buy and sell vehicles, houses and more. Cars, houses and everything else, in one tap.",
"Conhece pessoas em Los Santos. Desliza, combina, conversa.": "Meet people in Los Santos. Swipe, match, chat.",
"Pede polícia, EMS, mecânico, táxi e mais. Pede ajuda com a tua localização.": "Request police, EMS, a mechanic, a taxi and more. Ask for help with your location attached.",
"O clássico. Come, cresce e não te mordas. A cada cinco frutas fica mais rápido, e podes jogar com ou sem paredes. O clássico. Come, cresce e não te mordas. A cada cinco frutas fica mais rápido, e podes jogar com ou sem paredes.": "The classic. Eat, grow and don't bite yourself. It gets faster every five fruits, and you can play with or without walls. The classic. Eat, grow and don't bite yourself. It gets faster every five fruits, and you can play with or without walls.",
"Parte todos os tijolos sem deixar cair a bola. Tem tijolos resistentes, bónus que caem e níveis sem fim. Parte todos os tijolos sem deixar cair a bola. Tem tijolos resistentes, bónus que caem e níveis sem fim.": "Break all the bricks without dropping the ball. It has tough bricks, falling power-ups and endless levels. Break all the bricks without dropping the ball. It has tough bricks, falling power-ups and endless levels.",
"Os teus veículos, localização e garagem. Localiza, favorita, dá alcunhas.": "Your vehicles, their location and garage. Locate, favourite and nickname them.",
"Salas anónimas por alcunha. As mensagens ficam guardadas no servidor. Por alcunha. As mensagens ficam no servidor.": "Anonymous rooms by nickname. Messages are stored on the server. By nickname. Messages stay on the server.",
"Descobre o campo sem tocar numa mina. Três dificuldades, modo bandeira e abertura automática à volta dos números. Descobre o campo sem tocar numa mina. Três dificuldades, modo bandeira e abertura automática à volta dos números.": "Clear the field without touching a mine. Three difficulty levels, flag mode and automatic reveal around the numbers. Clear the field without touching a mine. Three difficulty levels, flag mode and automatic reveal around the numbers.",
"Todos os jogos do telemóvel num sítio só, com os teus recordes e o último que jogaste. Todos os jogos do telemóvel num sítio só, com os teus recordes e o último que jogaste.": "All the games on your phone in one place, with your records and the last one you played. All the games on your phone in one place, with your records and the last one you played.",
"Assistente com IA: dúvidas sobre o servidor e o telemóvel, contas, tempo e mais. Assistente com IA: dúvidas sobre o servidor e o telemóvel, contas, tempo e mais.": "AI assistant: questions about the server and the phone, calculations, weather and more. AI assistant: questions about the server and the phone, calculations, weather and more.",
"Vê onde estão a família e os amigos que partilham a localização contigo, e partilha a tua. Vê onde estão a família e os amigos que partilham a localização contigo, e partilha a tua.": "See where your family and friends are when they share their location with you, and share yours. See where your family and friends are when they share their location with you, and share yours.",
"Recebe e paga faturas de empresas e do estado. Paga ou recusa num toque.": "Receive and pay invoices from businesses and the government. Pay or decline in one tap.",
